"""Bank v2 for the injection GATE (bench/FASE56.md, Lote 2). Labels are mine or generated by rule (declared limit): nothing here was checked by a second person.
Queries about the LOCAL docs index (man pages, tldr, Arch wiki). kind 'pos': an excerpt should be injected and a result counts as a hit when the title of its chunk is in `gold`.
kind 'neg': NO excerpt should be injected. group:
  neg_word  a command/page name used as an ordinary word (templates x ~50 words, EN/ES)       -> HARD, correlated by word
  neg_tech  technical questions that are NOT about the shell (programming, electronics, ...)   -> HARD, hand written
  neg_easy  general knowledge questions (topics x templates)
  pos_named tldr command named in the question (EN/ES templates)                                -> from the tldr pages on this machine
  pos_sem   the tldr one-line description of a command, command name removed                    -> from the tldr pages on this machine
  pos_old   the 79 positives of bench/retrieval_bank.py
Split by md5 of the KEY (the head word of a template / the command / the query), so the words and commands of 'prueba' (test) never appear in 'ajuste' (tuning):
key digest mod 10 < 6 -> 'ajuste'. Parameters are chosen on 'ajuste' only; 'prueba' is evaluated once."""
import glob, hashlib, os, re

TLDR = os.path.expanduser("~/.cache/tealdeer/tldr-pages/pages.en")
WORDS = ("sort find time head tail join watch yes cut paste link kill which who true false test make cal date echo history diff patch file top mail wait sleep uniq split touch mount screen tee "
         "expand fold look column rev nice read write more less tr env id type alias source bind jobs clear reset apropos whereis").split()
CTX_EN = ["what does the English word '{w}' mean and how is it used in a sentence", "write a short poem that includes the word {w}", "translate the word {w} into Spanish and give three examples",
          "is there a famous song or movie called {w}", "explain the idea of {w} in everyday life, not in computing", "give me synonyms and antonyms of {w}"]
CTX_ES = ["qué significa la palabra {w} en inglés y cómo se usa en una frase", "escribe una frase corta que use la palabra {w}", "cuál es el origen de la palabra {w}"]
TECH = ["how do I sort a list of dictionaries in python", "what is the difference between a left join and an inner join in SQL", "how to find the maximum element of an array in C",
        "explain closures in javascript", "what is a race condition in multithreaded code", "how does garbage collection work in java", "write a regex that matches an email address",
        "what is the difference between TCP and UDP", "how do transistors work in a logic gate", "explain big O notation with examples", "how do I center a div with css",
        "what is dependency injection", "how do I read a csv file with pandas", "explain the difference between a process and a thread in theory", "what is a hash collision",
        "how does a binary search tree balance itself", "what is a pull request on github", "how do I write a unit test in rust", "what is the CAP theorem", "explain recursion with the fibonacci example",
        "how do I use async await in typescript", "what is a mutex", "how does public key cryptography work", "what is the difference between stack and heap memory", "how does DNS resolve a name in theory",
        "what is a REST API", "explain how a neural network learns", "how do I merge two sorted arrays", "what are design patterns", "how do I connect to a postgres database from python code",
        "cómo ordeno una lista en python", "qué es una clave foránea en una base de datos", "explica qué es la recursividad con un ejemplo", "cómo funciona un transistor", "qué diferencia hay entre TCP y UDP",
        "cómo escribo una prueba unitaria en java", "qué es un puntero en C", "cómo se calcula la complejidad de un algoritmo", "qué es la inyección de dependencias", "cómo hago una petición http en javascript",
        "explica qué es un hilo en programación concurrente", "cómo se centra un div en css", "qué es el protocolo HTTPS", "cómo funciona el cifrado de clave pública", "qué es una API REST",
        "cómo busco el elemento máximo de un arreglo en java", "qué es un árbol binario de búsqueda", "cómo funciona la memoria caché de un procesador", "qué es el patrón observador"]
TOPICS = ["the Roman Empire", "photosynthesis", "the French Revolution", "black holes", "jazz music", "the Amazon rainforest", "the printing press", "vaccines", "volcanoes", "the stock market", "chess",
          "the Renaissance", "honey bees", "the Moon landing", "ocean tides", "the Silk Road", "coffee", "marathon training", "the human heart", "Mount Everest", "origami", "the Mayan calendar",
          "plate tectonics", "classical ballet", "the water cycle", "solar panels", "Greek mythology", "the Industrial Revolution", "sleep and dreams", "bread baking"]
EASY_T = ["tell me about {t}", "háblame de {t}", "what are three interesting facts about {t}"]
OLD = None


def _key_split(key):
    return "ajuste" if int(hashlib.md5(key.encode()).hexdigest(), 16) % 10 < 6 else "prueba"


def tldr_commands():
    """-> {name: description} for tldr pages whose description does not contain the command name; deterministic order."""
    out = {}
    for sub in ("common", "linux"):
        for p in glob.glob(f"{TLDR}/{sub}/*.md"):
            name = os.path.basename(p)[:-3]
            if len(name) < 3 or not re.fullmatch(r"[a-z][a-z0-9]*", name) or name in WORDS:
                continue
            m = re.search(r"^> (.+?)\.?\s*$", open(p, encoding="utf-8", errors="ignore").read(), re.M)
            if m and not m.group(1).lower().startswith("see ") and re.search(r"\b" + re.escape(name) + r"\b", m.group(1).lower()) is None and len(m.group(1)) > 25:
                out[name] = m.group(1)
    return out


def bank():
    """-> list of dicts(query, kind, group, hard, gold, key, split)."""
    from retrieval_bank import bank as old
    b = []
    add = lambda q, kind, group, key, gold=(), hard=False: b.append(dict(query=q, kind=kind, group=group, hard=hard, gold=[g.lower() for g in gold], key=key, split=_key_split(key)))
    for w in WORDS:
        for c in CTX_EN + CTX_ES:
            add(c.format(w=w), "neg", "neg_word", w, hard=True)
    for q in TECH:
        add(q, "neg", "neg_tech", q, hard=True)
    for t in TOPICS:
        for c in EASY_T:
            add(c.format(t=t), "neg", "neg_easy", t)
    cmds = tldr_commands()
    names = sorted(cmds, key=lambda n: hashlib.md5(n.encode()).hexdigest())[:240]
    for n in names[:120]:
        add(f"how do I use {n} in the terminal", "pos", "pos_named", n, [n])
        add(f"cómo uso el comando {n}", "pos", "pos_named", n, [n])
    for n in names[120:240]:
        add(cmds[n], "pos", "pos_sem", n, [n])
    for x in old():
        if x["kind"] == "pos":
            add(x["query"], "pos", "pos_old", x["query"], x["gold"])
    return b


if __name__ == "__main__":
    import collections
    b = bank(); print(len(b))
    for k, v in sorted(collections.Counter((x["group"], x["split"]) for x in b).items()): print(k, v)
